function fewestPresses(start: number, target: number): number {
  const cap = 2 * Math.max(start, target) + 2;
  const dist = new Map<number, number>([[start, 0]]);
  const queue = [start];
  for (let h = 0; h < queue.length; h++) {
    const v = queue[h], d = dist.get(v)!;
    if (v === target) return d;
    for (const w of [v * 2, v - 1]) {
      if (w >= 1 && w <= cap && !dist.has(w)) { dist.set(w, d + 1); queue.push(w); }
    }
  }
  return -1;
}

