class Solution:
    def fewestPresses(self, start: int, target: int) -> int:
        cap = 2 * max(start, target) + 2
        dist = {start: 0}
        q = deque([start])
        while q:
            v = q.popleft()
            if v == target:
                return dist[v]
            for w in (v * 2, v - 1):
                if 1 <= w <= cap and w not in dist:
                    dist[w] = dist[v] + 1
                    q.append(w)
        return -1

